<?php
declare(strict_types=1);
use CoreCMS\Core\Url;
use CoreCMS\Modules\Tourism\TourismManager;
require_once dirname(__DIR__).'/Admin/TourismManager.php';
return static function(PDO $db,array $params,array $request,array $module):string{
 $manager=new TourismManager($db);$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$base=Url::to('/turlar');
 $tours=$manager->tours(['status'=>'published','q'=>(string)($_GET['q']??''),'destination_id'=>(string)($_GET['destination_id']??''),'category'=>(string)($_GET['category']??'')]);$destinations=$manager->destinations(true);
 $html='<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Turlar ve Aktiviteler</title><meta name="description" content="Destinasyonları keşfedin, size uygun turu bulun ve rezervasyon talebi gönderin."><link rel="stylesheet" href="'.Url::to('/modules/tourism/assets/css/tourism.css').'"></head><body class="tm-site"><header class="tm-header"><a class="tm-brand" href="'.$base.'">KEŞFET<span>.</span></a><nav><a href="'.$base.'">Turlar</a><a href="'.$base.'#destinasyonlar">Destinasyonlar</a><a href="'.$base.'#iletisim">İletişim</a></nav></header><main class="tm-container"><section class="tm-hero"><span>YENİ YERLER, UNUTULMAZ ANLAR</span><h1>Bir sonraki hikâyeniz<br><em>burada başlıyor.</em></h1><p>Özenle seçilmiş turlar ve deneyimlerle keşfe çıkın.</p><form class="tm-search" method="get"><input name="q" value="'.$e($_GET['q']??'').'" placeholder="Tur veya aktivite ara"><select name="destination_id"><option value="">Tüm destinasyonlar</option>';foreach($destinations as $d)$html.='<option value="'.(int)$d['id'].'"'.((string)($_GET['destination_id']??'')===(string)$d['id']?' selected':'').'>'.$e($d['name']).'</option>';$html.='</select><button class="tm-button">Keşfet</button></form></section><section class="tm-section"><div class="tm-heading"><div><span>SEÇİLMİŞ DENEYİMLER</span><h2>Popüler turlar</h2></div><small>'.count($tours).' deneyim</small></div><div class="tm-grid">';
 foreach($tours as $tour){$html.='<article class="tm-card"><a class="tm-card-image" href="'.$base.'/'.$e($tour['slug']).'">'.($tour['cover_image']?'<img src="'.$e($tour['cover_image']).'" alt="'.$e($tour['title']).'" loading="lazy">':'<span>KEŞFET</span>').'<i>'.$e($tour['category']).'</i></a><div class="tm-card-body"><small>'.$e($tour['destination_name']??'Destinasyon').'</small><h3><a href="'.$base.'/'.$e($tour['slug']).'">'.$e($tour['title']).'</a></h3><div class="tm-card-meta"><span>'.$e($tour['duration_hours']).' saat</span><strong>'.number_format((float)$tour['price'],0,',','.').' '.$e($tour['currency']).' <small>/ kişi</small></strong></div></div></article>';}
 $html.='</div>';if(!$tours)$html.='<div class="tm-empty"><h3>Uygun tur bulunamadı</h3><p>Arama kriterlerinizi değiştirip tekrar deneyin.</p></div></section>';
 if($destinations){$html.='<section class="tm-section" id="destinasyonlar"><div class="tm-heading"><div><span>GİDİLECEK YERLER</span><h2>Destinasyonlar</h2></div></div><div class="tm-destinations">';foreach($destinations as $d)$html.='<a href="'.$base.'?destination_id='.(int)$d['id'].'">'.($d['cover_image']?'<img src="'.$e($d['cover_image']).'" alt="'.$e($d['name']).'">':'').'<b>'.$e($d['name']).'</b></a>';$html.='</div></section>';}
 return $html.'<section class="tm-cta" id="iletisim"><h2>Yeni bir deneyime hazır mısınız?</h2><p>Size uygun turu seçin, rezervasyon talebinizi gönderin.</p></section></main><footer class="tm-footer">KEŞFET. · '.date('Y').'</footer></body></html>';
};
